using System;
using System.Net.NetworkInformation;
using System.Threading;
using System.Threading.Tasks;
namespace HealthCheck
{
public class ICMPHealthCheck : IHealthCheck
{
private string Host { get; set; }
private int Timeout { get; set; }
public ICMPHealthCheck(string host, int timeout)
{
Host = host;
Timeout = timeout;
}
public async Task<HealthCheckResult> CheckHealthAsync(
HealthCheckContext context,
CancellationToken cancellationToken = default)
{
try
{
using (var ping = new Ping())
{
var reply = await ping.SendPingAsync(Host);
switch (reply.Status)
{
case IPStatus.Success:
var msg = String.Format(
"IMCP to {0} took {1} ms.",
Host,
Front-end and Back-end Interactions Chapter 3
[ 110 ]
reply.RoundtripTime);
return (reply.RoundtripTime > Timeout)
? HealthCheckResult.Degraded(msg)
: HealthCheckResult.Healthy(msg);
default:
var err = String.Format(
"IMCP to {0} failed: {1}",
Host,
reply.Status);
return HealthCheckResult.Unhealthy(err);
}
}
}
catch (Exception e)
{
var err = String.Format(
"IMCP to {0} failed: {1}",
Host,
e.Message);
return HealthCheckResult.Unhealthy(err);
}
}
}
}
As we can see, we changed a couple of things, as follows:
We added a constructor accepting the two parameters we'd like to set
programmatically: host and timeout. The old hardcoded variables are now
properties so that we can use them to store the parameters upon
initialization and use them within the class afterward (such as within the
main method).
We created various different outcome messages containing the target host,
the ping outcome, and the round-trip duration (or the runtime error), and
added them as parameters to the HealthCheckResult return objects.
That's pretty much about it. Now, we just need to set the host name and the
timeout programmatically since the old hardcoded defaults are now gone. In order to
do that, we have to update our middleware setup in the Startup.cs file.
