SELECT COUNT(*)
FROM [Cities] AS [c]
WHERE [c0].[Id] = [c].[CountryId]) AS [TotCities]
FROM [Countries] AS [c0]
ORDER BY [c0].[Name]
OFFSET @__p_0 ROWS FETCH NEXT @__p_1 ROWS ONLY
That's not bad; the LINQ to SQL provider converted it using a subquery, which is a
good choice in terms of performance. The OFFSET part of the SQL query, together
with the DBCommand Parameters mentioned in the preceding code snippet, handles
the pagination and ensures that we're only getting the rows we've been asking for.
However, the Visual Studio Output window is not the only way to take a look at
those SQL queries – we can provide ourselves with an even better alternative by
implementing a simple, yet effective, extension method, as we're going to see in the
following sections.
Getting the SQL code programmatically
The Output window is good enough for most scenarios, but what if we want to
retrieve the SQL code from an IQueryable<T> programmatically? Such an option
might be very useful to debug (or conditionally debug) some parts of our app,
especially if we want to automatically save these SQL queries outside the Output
window (for example, a log file or a log aggregator service).
In order to achieve such a result, we need to create a dedicated helper function that
will be able to do that using System.Reflection. Let's quickly do that and test out
how it works.
From the Solution Explorer, right-click the /Data/ folder, create a new
IQueryableExtensions.cs file, and fill its content with the following source code:
using Microsoft.EntityFrameworkCore.Query;
using Microsoft.EntityFrameworkCore.Query.SqlExpressions;
Back-end and Front-end Debugging Chapter 8
[ 432 ]
using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
namespace WorldCities.Data
{
public static class IQueryableExtension
{
public static string ToSql<T>(this IQueryable<T> query)
{
var enumerator = query.Provider
.Execute<IEnumerable<T>>
(query.Expression).GetEnumerator();
var relationalCommandCache = enumerator
.Private("_relationalCommandCache");
var selectExpression = relationalCommandCache
.Private<SelectExpression>("_selectExpression");
var factory = relationalCommandCache
.Private<IQuerySqlGeneratorFactory>
("_querySqlGeneratorFactory");
var sqlGenerator = factory.Create();
var command = sqlGenerator.GetCommand(selectExpression);
string sql = command.CommandText;
return sql;
}
private static object Private(this object obj, string
privateField) =>
obj?.GetType()
.GetField(privateField, BindingFlags.Instance |
BindingFlags.NonPublic)?
.GetValue(obj);
private static T Private<T>(this object obj, string
privateField) =>
(T)obj?
.GetType()
.GetField(privateField, BindingFlags.Instance |
BindingFlags.NonPublic)?
.GetValue(obj);
}
}
